 private static void checkManagement()throws Exception{
  var search=(net.minecraft.client.gui.components.EditBox)member("moduleSearch");var add=(net.minecraft.client.gui.components.Button)member("add");var copy=(net.minecraft.client.gui.components.Button)member("copyModule");var up=(net.minecraft.client.gui.components.Button)member("moveModuleUp");
  var sync=HeartDashboardScreen.class.getDeclaredMethod("sync");sync.setAccessible(true);var list=HeartDashboardScreen.class.getDeclaredMethod("sidebarModules");list.setAccessible(true);
  if(add.getWidth()<=copy.getWidth()||add.getX()+add.getWidth()>=copy.getX()||copy.getX()+copy.getWidth()>=up.getX())throw new AssertionError("Add/Copy widths or gaps wrong");
  search.setValue("l");screen.panel.setFocused(search);search.setFocused(true);if(!screen.panel.charTyped('e',0)||!screen.panel.charTyped('g',0))throw new AssertionError("Search typing rejected");sync.invoke(screen.panel);if(!search.getValue().equals("leg")||!search.isFocused()||((java.util.List<?>)list.invoke(screen.panel)).size()!=30)throw new AssertionError("Search focus/global filter failed");
  if(!screen.panel.keyPressed(69,0,0))throw new AssertionError("Inventory binding escaped search editor");
  search.setValue("#60");sync.invoke(screen.panel);var rows=(java.util.List<net.minecraft.client.gui.components.Button>)member("rows");if(((java.util.List<?>)list.invoke(screen.panel)).size()!=1||!rows.getFirst().getMessage().getString().endsWith("#60")||!copy.active)throw new AssertionError("Original number or copy availability lost under filtering");
  search.setValue("no matching module xyz");sync.invoke(screen.panel);if(!((java.util.List<?>)list.invoke(screen.panel)).isEmpty()||rows.stream().anyMatch(b->b.visible)||copy.active)throw new AssertionError("Empty search retained rows/copy");
  search.setValue("#60");sync.invoke(screen.panel);
  // Emulate the authoritative copy response; a number filter must reveal the new module.
  var menu=screen.panel.getMenu();var data=menu.snapshot();var items=data.getList("Modules",10);var tag=items.getCompound(items.size()-1).copy();var id=java.util.UUID.randomUUID();tag.putUUID("Id",id);items.add(tag);data.putUUID("Selected",id);
  var track=HeartDashboardScreen.class.getDeclaredMethod("trackAdd",String.class);track.setAccessible(true);track.invoke(screen.panel,tag.getString("Type"));var stack=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.PAPER);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));menu.getSlot(0).set(stack);sync.invoke(screen.panel);
  if(!member("selected").equals(id)||!search.getValue().isEmpty()||!copy.active)throw new AssertionError("Copy response did not select/reveal independent module");
  data.putInt("ModuleLimit",61);stack=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.PAPER);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));menu.getSlot(0).set(stack);sync.invoke(screen.panel);if(add.active||copy.active)throw new AssertionError("Capacity did not disable add/copy");
  data.putInt("ModuleLimit",128);stack=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.PAPER);stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(data));menu.getSlot(0).set(stack);search.setValue("#61");search.setFocused(false);sync.invoke(screen.panel);
  System.out.println("Module management UI passed: full search, focus, original numbering, copy selection, capacity, Add wider than Copy");
 }
